(()=>{document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll("main h2[id], main h3[id]");if(!e.length)return;e.forEach(e=>{let t=e.querySelector(".icon");t||(t=document.createElement("span"),t.className="icon",t.textContent="•",t.style.marginRight="0.5em",e.insertBefore(t,e.firstChild))});const t=new Set(JSON.parse(localStorage.getItem("readSections")||"[]"));t.forEach(e=>{const t=document.querySelector(`#${CSS.escape(e)} .icon`);t&&t.classList.add("read")});const n=new IntersectionObserver(e=>{e.forEach(e=>{const s=e.target.id,n=e.target.querySelector(".icon");if(!n)return;e.isIntersecting?(n.classList.add("active","read"),t.add(s),localStorage.setItem("readSections",JSON.stringify([...t]))):n.classList.remove("active")})},{threshold:.6});e.forEach(e=>n.observe(e))})})()